// Generated by Cypress Author on 2026-10-22
//
// REL 03 · REL 05 · REL 08 (servidor) — Plano_de_Testes_QA_MatchWallet.md §8 (docs-test/areas/rel.md).
// Cada teste usa uma CARTEIRA PRÓPRIA (criada e desativada aqui), com versões e relatórios que só
// ela tem; o admin real só executa as ações de equipe.
//
// Limites do Cypress: o conteúdo do PDF (ativos, pesos, quebra de página, impressão) não é legível
// — o pdfmake embute fontes e comprime os textos. REL 05 prova a fidelidade histórica pelos BYTES
// (o arquivo antigo é imutável depois de uma nova versão) e o texto/impressão ficam para conferência
// manual. A interrupção de resposta de REL 08 (cliente perde a resposta) só é simulável na UI
// stubada, em `stubbed/admin-relatorios`.

import { competenciaRelativa } from '../../support/commands/fluxos'

interface Gerado {
  id: string
  carteiraId: string
  mesReferencia: string
  nomeArquivo: string
  tamanhoBytes: number
}

const carteirasCriadas: string[] = []

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

function novaCarteira() {
  return cy.criarCarteiraDeTeste().then((id) => {
    carteirasCriadas.push(id)
    return id
  })
}

function gerar(carteiraId: string, mesReferencia: string, extras: Record<string, unknown> = {}) {
  return cy.gerarRelatorioComEspera({ carteiraId, mesReferencia, ...extras })
}

function baixar(id: string) {
  return cy.apiRequest<string>({
    method: 'GET',
    url: `/relatorios/${id}/download`,
    encoding: 'binary',
  })
}

function acervo() {
  return cy
    .apiRequest<{ items: Array<{ id: string }>; total: number }>({
      method: 'GET',
      url: '/relatorios/meus-relatorios?pageSize=100',
    })
    .its('body')
}

describe('Plano QA · Relatórios no servidor', () => {
  after(() => {
    comoAdmin()
    for (const id of carteirasCriadas) cy.desativarCarteira(id)
  })

  it('REL 03 · competência inválida e comentário nos limites → inválidos recusados (400), comentário opcional e texto estranho aceito como dado', () => {
    const mes = competenciaRelativa()
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      cy.publicarVersaoDeTeste(carteiraId, mes, [100])

      // Competência vazia, malformada e mês 00/13: nada é gerado.
      for (const invalida of [
        '',
        '2026-00',
        '2026-13',
        '26-10',
        '2026-1',
        'abcd-ef',
        '2026-10-01',
      ]) {
        gerar(carteiraId, invalida).its('status', { log: false }).should('be.oneOf', [400, 422])
      }

      // Sem comentário: opcional.
      gerar(carteiraId, mes).then(({ status, body }: Cypress.Response<Gerado>) => {
        expect(status).to.eq(201)
        expect(body.mesReferencia).to.eq(mes)
      })

      // Exatamente 2000 caracteres, com acentos, quebras de linha e marcação HTML.
      const abertura =
        'Mercado: ação, previdência e câmbio ç ã é.\nSegunda linha <b>negrito</b> <script>window.__x=1</script> & "aspas"\n'
      const comentario = abertura + 'x'.repeat(2000 - abertura.length)
      expect(comentario).to.have.length(2000)
      gerar(carteiraId, mes, { comentarioMercado: comentario, forcar: true }).then(
        ({ status, body }: Cypress.Response<Gerado>) => {
          expect(status).to.eq(201)
          // O arquivo existe e é um PDF íntegro (o HTML virou texto, não quebrou a geração).
          baixar(body.id).then(({ status: baixou, headers, body: bytes }) => {
            expect(baixou).to.eq(200)
            expect(String(headers['content-type'])).to.contain('application/pdf')
            expect(bytes.slice(0, 4)).to.eq('%PDF')
            expect(bytes.trimEnd().endsWith('%%EOF'), 'PDF termina com %%EOF').to.eq(true)
          })
        },
      )

      // 2001 caracteres: acima do limite, recusado.
      gerar(carteiraId, mes, { comentarioMercado: 'x'.repeat(2001), forcar: true })
        .its('status')
        .should('be.oneOf', [400, 422])
    })
  })

  it('REL 05 · relatório de M-1 depois de nova composição em M → arquivo antigo idêntico byte a byte, do tamanho registrado e na competência certa', () => {
    const mes = competenciaRelativa()
    const mesAnterior = competenciaRelativa(-1)
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      cy.publicarVersaoDeTeste(carteiraId, mesAnterior, [50, 50])

      gerar(carteiraId, mesAnterior, {
        comentarioMercado: 'Comentário histórico de M-1: ação ç',
      }).then(({ status, body: antigo }: Cypress.Response<Gerado>) => {
        expect(status).to.eq(201)
        expect(antigo.mesReferencia).to.eq(mesAnterior)

        baixar(antigo.id).then(({ headers, body: antes }) => {
          expect(antes.slice(0, 4)).to.eq('%PDF')
          expect(antes.length, 'tamanho do arquivo = tamanhoBytes').to.eq(antigo.tamanhoBytes)
          expect(String(headers['content-disposition'])).to.contain(antigo.nomeArquivo)
          expect(antigo.nomeArquivo).to.contain(mesAnterior)

          // Nova composição em M, com pesos diferentes, e relatório de M.
          cy.publicarVersaoDeTeste(carteiraId, mes, [70, 30])
          gerar(carteiraId, mes).then(({ status: gerou, body: novo }: Cypress.Response<Gerado>) => {
            expect(gerou).to.eq(201)
            expect(novo.nomeArquivo).to.contain(mes)

            // M-1 segue exatamente como foi emitido.
            baixar(antigo.id).then(({ body: depois }) => {
              expect(depois, 'bytes de M-1 depois de publicar M').to.eq(antes)
            })
            // E M é outro documento.
            baixar(novo.id).then(({ body: atual }) => {
              expect(atual.slice(0, 4)).to.eq('%PDF')
              expect(atual.length).to.eq(novo.tamanhoBytes)
              expect(atual).not.to.eq(antes)
            })

            // Os dois convivem no acervo (competências diferentes, nenhum substituiu o outro).
            acervo().should(({ items }) => {
              const ids = items.map((i) => i.id)
              expect(ids).to.include(antigo.id)
              expect(ids).to.include(novo.id)
            })
          })
        })
      })
    })
  })

  it('REL 08 · emitir de novo a mesma competência → sem forçar é recusado sem duplicar; com forçar substitui e preserva um único ativo', () => {
    const mes = competenciaRelativa()
    comoAdmin()

    novaCarteira().then((carteiraId) => {
      cy.publicarVersaoDeTeste(carteiraId, mes, [100])

      gerar(carteiraId, mes, { comentarioMercado: 'Primeira emissão' }).then(
        ({ status, body: primeiro }: Cypress.Response<Gerado>) => {
          expect(status).to.eq(201)

          acervo().then(({ total: antes }) => {
            // Repetir sem `forcar` (ex.: retry depois de perder a resposta): não duplica.
            gerar(carteiraId, mes, { comentarioMercado: 'Retry' }).its('status').should('eq', 409)
            acervo().its('total').should('eq', antes)

            // Reemissão deliberada, com comentário diferente.
            gerar(carteiraId, mes, {
              comentarioMercado: 'Revisão do comentário',
              forcar: true,
            }).then(({ status: reemitiu, body: segundo }: Cypress.Response<Gerado>) => {
              expect(reemitiu).to.eq(201)
              expect(segundo.id).not.to.eq(primeiro.id)
              expect(segundo.nomeArquivo).not.to.eq(primeiro.nomeArquivo)

              // Só a emissão nova fica ativa no acervo; o total não cresce.
              acervo().should(({ items, total }) => {
                const ids = items.map((i) => i.id)
                expect(ids).to.include(segundo.id)
                expect(ids).not.to.include(primeiro.id)
                expect(total).to.eq(antes)
              })
              baixar(segundo.id).its('status').should('eq', 200)
            })
          })
        },
      )
    })
  })
})
